namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Code { get; set; }
    public required string Description { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Title { get; set; }
    public required string Bio { get; set; }
    public required string Email { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string Location { get; set; }
    public int MaxEnrollment { get; set; }
    public int CurrentEnrollment { get; set; }
    public bool IsFeatured { get; set; }

    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;

    public int InstructorId { get; set; }
    public Instructor Instructor { get; set; } = null!;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]{6,12}$", ErrorMessage = "Student ID must be 6–12 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Exploration of numbers, structures, and abstract reasoning." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and critical analysis of texts." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Understanding matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Examination of past events and their impact on the modern world." },
        ];

        _instructors =
        [
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 60 papers and holds two patents in natural language processing.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Patel", Title = "Associate Professor of Computer Science", Bio = "Dr. Patel focuses on distributed systems and cloud computing. He spent a decade in industry at leading tech companies before joining academia.", Email = "rpatel@university.edu" },
            new() { Id = 3, Name = "Dr. Maria Gonzalez", Title = "Professor of Mathematics", Bio = "Dr. Gonzalez is an expert in combinatorics and graph theory. She is a recipient of the National Science Foundation CAREER Award.", Email = "mgonzalez@university.edu" },
            new() { Id = 4, Name = "Dr. James O'Brien", Title = "Senior Lecturer in English", Bio = "Dr. O'Brien has authored three novels and is a specialist in contemporary American fiction and creative writing pedagogy.", Email = "jobrien@university.edu" },
            new() { Id = 5, Name = "Dr. Sarah Kim", Title = "Professor of Physics", Bio = "Dr. Kim leads the university's quantum optics laboratory and has contributed to breakthrough experiments in quantum entanglement.", Email = "skim@university.edu" },
            new() { Id = 6, Name = "Dr. William Harris", Title = "Associate Professor of History", Bio = "Dr. Harris researches early modern European history with a focus on the social impact of the printing press.", Email = "wharris@university.edu" },
            new() { Id = 7, Name = "Dr. Linda Zhao", Title = "Assistant Professor of Mathematics", Bio = "Dr. Zhao works on applied statistics and data science, bridging the gap between mathematical theory and real-world applications.", Email = "lzhao@university.edu" },
        ];

        _courses =
        [
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "An introductory course covering fundamental concepts of programming, data structures, and algorithmic thinking using Python.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", MaxEnrollment = 120, CurrentEnrollment = 98, IsFeatured = true, DepartmentId = 1, InstructorId = 1 },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of core data structures (lists, trees, graphs, hash tables) and algorithm design techniques including divide-and-conquer, dynamic programming, and greedy algorithms.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Science Hall 305", MaxEnrollment = 60, CurrentEnrollment = 55, IsFeatured = true, DepartmentId = 1, InstructorId = 2 },
            new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction processing, and an introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", Location = "Tech Building 110", MaxEnrollment = 45, CurrentEnrollment = 40, IsFeatured = false, DepartmentId = 1, InstructorId = 2 },
            new() { Id = 4, Code = "CS 450", Title = "Artificial Intelligence", Description = "Covers search algorithms, knowledge representation, machine learning fundamentals, and neural networks.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", Location = "Science Hall 201", MaxEnrollment = 40, CurrentEnrollment = 38, IsFeatured = true, DepartmentId = 1, InstructorId = 1 },
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications in science and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 100", MaxEnrollment = 150, CurrentEnrollment = 130, IsFeatured = true, DepartmentId = 2, InstructorId = 3 },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to systems of equations.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", Location = "Math Building 200", MaxEnrollment = 60, CurrentEnrollment = 42, IsFeatured = false, DepartmentId = 2, InstructorId = 3 },
            new() { Id = 7, Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", Location = "Math Building 105", MaxEnrollment = 50, CurrentEnrollment = 35, IsFeatured = false, DepartmentId = 2, InstructorId = 7 },
            new() { Id = 8, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Fundamentals of academic writing, argumentation, research methods, and critical reading.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Humanities 301", MaxEnrollment = 30, CurrentEnrollment = 28, IsFeatured = false, DepartmentId = 3, InstructorId = 4 },
            new() { Id = 9, Code = "ENG 250", Title = "American Literature", Description = "Survey of major American literary works from the colonial period to the present, including novels, poetry, and essays.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", Location = "Humanities 210", MaxEnrollment = 35, CurrentEnrollment = 20, IsFeatured = true, DepartmentId = 3, InstructorId = 4 },
            new() { Id = 10, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 3:00–5:00 PM", Location = "Physics Building 100", MaxEnrollment = 80, CurrentEnrollment = 65, IsFeatured = false, DepartmentId = 4, InstructorId = 5 },
            new() { Id = 11, Code = "PHYS 301", Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", Location = "Physics Building 210", MaxEnrollment = 30, CurrentEnrollment = 22, IsFeatured = true, DepartmentId = 4, InstructorId = 5 },
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "A survey of major civilizations, cultures, and events from prehistory through the late medieval period.", Credits = 3, Schedule = "Mon/Wed 3:00–4:15 PM", Location = "Liberal Arts 105", MaxEnrollment = 50, CurrentEnrollment = 33, IsFeatured = false, DepartmentId = 5, InstructorId = 6 },
            new() { Id = 13, Code = "HIST 240", Title = "The Renaissance & Reformation", Description = "Examines the cultural, intellectual, and religious transformations of Europe from the 14th to the 17th century.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", Location = "Liberal Arts 200", MaxEnrollment = 35, CurrentEnrollment = 18, IsFeatured = false, DepartmentId = 5, InstructorId = 6 },
        ];

        // Wire up navigation properties
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
            course.Instructor = _instructors.First(i => i.Id == course.InstructorId);
        }
    }

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

