                <label for="studentId" class="form-label">Student ID</label>
                <input type="text" id="studentId" name="StudentId" class="form-control" required
                       pattern="[A-Za-z0-9]{6,12}" title="6–12 alphanumeric characters" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <select id="courseId" name="CourseId" class="form-select" required>
                    <option value="">— Select a course —</option>
                    @foreach (var course in Catalog.GetCourses())
                    {
                        <option value="@course.Id" selected="@(PreselectedCourseId == course.Id)">
                            @course.Code — @course.Title
                        </option>
                    }
                </select>
            </div>

            <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
            <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
        </form>
    </div>
</div>

