    <div class="alert alert-danger">
        <h4>Submission Error</h4>
        <p>@errorMessage</p>
        <a href="/enroll" class="btn btn-outline-danger">Go Back</a>
    </div>
}
else
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Request Submitted</h4>
        <p>Thank you, <strong>@Model.FullName</strong> (ID: @Model.StudentId).</p>
        <p>Your enrollment request for <strong>@selectedCourse?.Code — @selectedCourse?.Title</strong> has been received and is being processed.</p>
        <hr />
        <p class="mb-0">You will receive a confirmation email once your request is reviewed.</p>
    </div>
    <a href="/courses" class="btn btn-primary">Back to Catalog</a>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    private Course? selectedCourse;
    private string? errorMessage;

    protected override void OnInitialized()
    {
        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.StudentId) ||
            Model.CourseId <= 0)
        {
            errorMessage = "Please fill in all required fields.";
            return;
        }

        selectedCourse = Catalog.GetCourse(Model.CourseId);
        if (selectedCourse is null)
        {
            errorMessage = "The selected course was not found.";
        }
    }
}

